<section class="admin-panel roles-directory"><header><div><h2>Directorio de roles</h2><p>Consulta qué representa cada rol y cuántos permisos contiene.</p></div><span><?= e(count($roles)) ?> registrados</span></header><?php if ($roles === []): ?><div class="roles-empty"><h3>Aún no hay roles configurados</h3><p>Crea un rol a partir de las tareas reales del puesto.</p></div><?php else: ?><div class="roles-list"><?php foreach ($roles as $role): ?><article class="role-card"><div class="role-card-mark" aria-hidden="true"><?= e(strtoupper(substr($role['name'], 0, 1))) ?></div><div class="role-card-copy"><div><h3><?= e($role['name']) ?></h3><?php if ((int) $role['is_system'] === 1): ?><span class="role-type is-system">Sistema</span><?php else: ?><span class="role-type">Configurable</span><?php endif ?></div><p><?= e($role['description'] ?? 'Sin descripción del propósito de este rol.') ?></p><div class="role-card-meta"><span><strong><?= e($role['permission_count']) ?></strong> <?= (int) $role['permission_count'] === 1 ? 'permiso' : 'permisos' ?></span><code><?= e($role['code']) ?></code></div></div><div class="role-card-action"><?php if ((int) $role['is_system'] === 1): ?><span>Protegido</span><small>Garantiza la administración base</small><?php elseif ($capabilities['roles.edit'] ?? false): ?><a class="admin-secondary-button" data-admin-form-link href="/admin/roles/edit?id=<?= e($role['id']) ?>">Configurar permisos</a><?php else: ?><span>Solo consulta</span><?php endif ?></div></article><?php endforeach ?></div><?php endif ?></section>
